{
    const cutoffMs = Date.parse(cutoffIso);
    const deals: DealRecord[] = [];

    for (const p of rawPages) {
      const editedMs = Date.parse(p.last_edited_time);
      if (!Number.isFinite(editedMs) || editedMs < cutoffMs) {
        continue;
      }

      const properties = p.properties ?? {};
      const title = this.extractNotionTitle(properties);
      const notes = this.extractRichTextProperty(properties, notesPropertyName).trim();
      if (!notes) {
        continue;
      }

      deals.push({
        id: p.id,
        title,
        lastEditedTime: p.last_edited_time,
        url: p.url,
        notes,
      });
    }

    return deals;
  }

