{
    const stalled = assessments.filter((a) => a.stalled);
    const active = assessments.filter((a) => !a.stalled);

    const header = [
      `<b>Pipeline digest</b>`,
      `<i>${this.escapeHtml(cutoffIso)} → ${this.escapeHtml(nowIso)}</i>`,
      '',
      `Deals analyzed: <b>${assessments.length}</b>`,
      `Stalled: <b>${stalled.length}</b>`,
      `Active: <b>${active.length}</b>`,
    ].join('\n');

    const sections: string[] = [header];

    if (stalled.length > 0) {
      sections.push('');
      sections.push('<b>Stalled deals (need attention)</b>');
      for (const a of stalled) {
        sections.push(this.formatDealLine(a));
      }
    }

    if (active.length > 0) {
      sections.push('');
      sections.push('<b>Active deals (next steps)</b>');
      for (const a of active) {
        sections.push(this.formatDealLine(a));
      }
    }

    if (assessments.length === 0) {
      sections.push('');
      sections.push('No recently edited deals with non-empty notes were found in the lookback window.');
    }

    return this.splitTelegramMessages(sections.join('\n'));
  }

